-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["3315b12b97e415b7"] = { "Per mantenere i rapporti e i commerci con i loro cugini, i nani di ⟦Ironforge=Forgiardente⟧ costruirono due enormi arcate, il ⟦Thandol Span=Viadotto di Thandol⟧, per colmare la distanza tra il Khaz Modan e Lordaeron. Rafforzati dal commercio reciproco, i due regni prosperarono. Dopo la morte di Madoran e di Khardros, i loro figli commissionarono insieme due grandi statue in onore dei loro padri.", "." },
  ["33163b8d49e86d5a"] = { "Per un certo tempo le tre fazioni mantennero una pace precaria, ma le tensioni esplosero quando il gran re ⟦Anvilmar=Forgiamara⟧ morì di vecchiaia. I tre clan al potere entrarono in guerra per il controllo della stessa ⟦Ironforge=Forgiardente⟧. La guerra civile dei nani infuriò sotto terra per molti anni. Alla fine i Barbabronzea, che avevano l'esercito permanente più grande, scacciarono i Ferroscuro e i Granmartello da sotto la montagna.", "." },
  ["3350667823761e35"] = { "Argus,\n\ncome sai, sono sommerso fino al collo dalle richieste di riparazione dell'esercito. Non posso lamentarmi di tutto questo lavoro, ma sta esaurendo le mie scorte di ferro.\n\nNon ho abbastanza ferro per i ferri di cavallo. So che tu ne tieni sempre una bella scorta: vorrei farmi prestare 50 paia di ferri finché non mi arriva la prossima spedizione di ferro.\n\nCon gratitudine,\n-Verner", "." },
  ["3352c9e628fc232b"] = { "Samla,\n\nmentre seguiamo il nostro lord Arthas verso nord, sempre più a nord, il mio cuore si fa pesante. Un tempo risplendeva della Luce, ma ora avverto un oscurarsi nello spirito del giovane paladino. Il suo zelo è offuscato da un cupo rimuginare, per qualche incubo nella sua anima che non riesco a indovinare...\n\nPresto approderemo nelle distese ghiacciate. Anche se molti dei suoi uomini si ammalano per il freddo e per le battaglie contro bestie putride, Arthas ci dice che ciò che cerca nel ghiaccio cambierà le sorti della guerra. Ma le sue parole non mi hanno dato conforto, perché dopo averle pronunciate... il sorriso torvo stampato sulle sue labbra arricciate mi ha gelato più a fondo di qualunque bufera.\n\nPrega per noi, Samla, e prega per il nostro mondo,\n\nTorgal", "." },
  ["3358749832ffc4a0"] = { "La mano mi trema mentre ricordo i dettagli di quella notte, quando Sven era via e la sua famiglia fu condannata ad affrontare da sola i Cavalieri Neri. Di nuovo il rimpianto mi artiglia, perché ero lì e avrei potuto insorgere contro quei demoni del ⟦Deadwind Pass=Valico Ventomorto⟧. Ma è un falso rimpianto. È lo stesso che tormenta chiunque sopravviva a una tragedia. So che, se avessi lasciato il mio nascondiglio, sarei stato ucciso anch'io, il mio corpo squarciato e lacerato, e i suoi pezzi sparsi così lontano che nessuno mi avrebbe riconosciuto.", "." },
  ["33c5183b3427666a"] = { "Trovato nella remota foresta pluviale del ⟦Un'Goro Crater=Cratere di Un'Goro⟧, questo uovo conteneva un tempo l'embrione di un gigantosauro. Il materiale genetico del sauro si è rivelato prezioso per gli ecologisti della Lega, che sono più vicini che mai a mettere a punto un siero contro il veleno debilitante dei gigantosauri.", "." },
})
